@push('scripts')<script>
(() => { const app=document.querySelector('#puzzleApp'), p=JSON.parse(app.dataset.puzzle), type=app.dataset.type, key='innsatt.tidsfordriv.'+type+'.'+p.id, status=document.querySelector('#puzzleStatus'); let state=JSON.parse(localStorage.getItem(key)||'null')||{};
const save=()=>localStorage.setItem(key,JSON.stringify(state)); const esc=s=>String(s).replace(/[&<>]/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[x]));
if(type==='binaer'){let g=state.g||p.given.map((r,i)=>r.length?r:p.solution[i].map(()=>null));app.innerHTML='<div class="binary-grid">'+p.solution.map((r,y)=>r.map((v,x)=>`<button class="puzzle-cell ${p.given[y]?.[x]!==null&&p.given[y]?.[x]!==undefined?'given':''}" data-y="${y}" data-x="${x}">${g[y][x]??''}</button>`).join('')).join('')+'</div>';app.onclick=e=>{let b=e.target.closest('button[data-y]');if(!b||b.classList.contains('given'))return;let y=b.dataset.y,x=b.dataset.x;g[y][x]=g[y][x]===null?0:g[y][x]===0?1:null;b.textContent=g[y][x]??'';state.g=g;save()};}
else if(type==='nonogram'){const clues=a=>a.map(r=>r.join('').split('0').filter(Boolean).map(x=>x.length).join(' ')||'0');let g=state.g||p.grid.map(r=>r.map(()=>0));app.innerHTML='<div class="nonogram-wrap"><div class="nonogram-col">'+clues(p.grid[0].map((_,i)=>p.grid.map(r=>r[i]))).map(x=>`<span>${x}</span>`).join('')+'</div><div>'+p.grid.map((r,y)=>`<div class="nonogram-row"><b>${clues([r])[0]}</b>${r.map((_,x)=>`<button class="puzzle-cell n${g[y][x]}" data-y="${y}" data-x="${x}">${g[y][x]===2?'×':''}</button>`).join('')}</div>`).join('')+'</div></div>';app.onclick=e=>{let b=e.target.closest('button');if(!b)return;let y=b.dataset.y,x=b.dataset.x;g[y][x]=(g[y][x]+1)%3;b.className='puzzle-cell n'+g[y][x];b.textContent=g[y][x]===2?'×':'';state.g=g;save()};}
else if(type==='tallpyramide'){let g=state.g||p.given;app.innerHTML='<div class="pyramid">'+p.solution.map((r,y)=>`<div>${r.map((_,x)=>`<input aria-label="Rute ${y+1}-${x+1}" data-y="${y}" data-x="${x}" ${p.given[y][x]!==null?'value="'+p.given[y][x]+'" readonly':''}>`).join('')}</div>`).join('')+'</div>';app.oninput=e=>{state.g=[...app.querySelectorAll('input')].map(i=>i.value);save()};}
else if(type==='labyrint'){let y=1,x=1; app.innerHTML='<div class="maze" tabindex="0" aria-label="Labyrint">'+p.grid.map((r,Y)=>[...r].map((v,X)=>`<span data-y="${Y}" data-x="${X}" class="${v==='#'?'wall':''}">${v==='S'?'●':v==='M'?'M':''}</span>`).join('')).join('')+'</div>';let maze=app.firstChild;maze.onkeydown=e=>{let d={ArrowUp:[-1,0],w:[-1,0],ArrowDown:[1,0],s:[1,0],ArrowLeft:[0,-1],a:[0,-1],ArrowRight:[0,1],d:[0,1]}[e.key];if(!d)return;e.preventDefault();let ny=y+d[0],nx=x+d[1];if(p.grid[ny][nx]!=='#'){maze.querySelector(`[data-y="${y}"][data-x="${x}"]`).textContent='';y=ny;x=nx;maze.querySelector(`[data-y="${y}"][data-x="${x}"]`).textContent='●';if(p.grid[y][x]==='M')status.textContent='Du fant målet!'}};}
else if(type==='minikryssord'){app.innerHTML='<div class="crossword">'+p.grid.map((r,y)=>[...r].map((v,x)=>v==='#'?'<span class="black"></span>':`<input maxlength="1" aria-label="Rute ${y+1}-${x+1}" data-y="${y}" data-x="${x}">`).join('')).join('')+'</div><ol class="crossword-clues">'+p.entries.map(e=>`<li><b>${e.n}.</b> ${esc(e.clue)} (${e.word.length})</li>`).join('')+'</ol>';app.oninput=e=>{e.target.value=e.target.value.toUpperCase();state.g=[...app.querySelectorAll('input')].map(i=>i.value);save()};}
else {let n=p.size;app.innerHTML='<div class="dots" style="grid-template-columns:repeat('+n+',1fr)">'+Array.from({length:n*n},(_,i)=>'<i></i>').join('')+'</div><p>Spiller 1: ______ Poeng: ___ &nbsp; Spiller 2: ______ Poeng: ___</p>';}
document.querySelector('#clearPuzzle').onclick=()=>{if(confirm('Dette sletter fremdriften på denne oppgaven. Fortsette?')){localStorage.removeItem(key);location.reload()}};document.querySelector('#showSolution').onclick=()=>{if(confirm('Løsningen vises nå. Fortsette?')){status.textContent='Løsning: '+(p.solution?JSON.stringify(p.solution):p.grid?p.grid.join(' / '):p.entries?.map(e=>e.word).join(', ')||'Se fasit for spilleregler.')}};
})();</script>@endpush
